cliSteps.command:
cat > content-bucket-policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "CloudFrontReadOnlyOAC",
      "Effect": "Allow",
      "Principal": {"Service": "cloudfront.amazonaws.com"},
      "Action": "s3:GetObject",
      "Resource": "arn:aws:s3:::cf-secure-content-lab-<ACCOUNT_ID>/*",
      "Condition": {"StringEquals": {"AWS:SourceArn": "[DISTRIBUTION_ARN]"}}
    }
  ]
}
EOF
aws s3api put-bucket-policy --bucket cf-secure-content-lab-<ACCOUNT_ID> --policy file://content-bucket-policy.json --profile <LAB_PROFILE> --region eu-west-2

cat > security-headers-policy.json <<'EOF'
{
  "Name": "cf-secure-content-lab-security-headers",
  "Comment": "Training security headers policy",
  "SecurityHeadersConfig": {
    "ContentTypeOptions": {"Override": true},
    "StrictTransportSecurity": {
      "AccessControlMaxAgeSec": 31536000,
      "IncludeSubdomains": false,
      "Preload": false,
      "Override": true
    }
  }
}
EOF
aws cloudfront create-response-headers-policy --response-headers-policy-config file://security-headers-policy.json --profile <LAB_PROFILE>

